 subroutine oracle_scope_begin(key,event)
  character(len=*), intent(in) :: key
  integer, intent(in) :: event
  integer :: ancestor
  logical :: retain_counters
  retain_counters=oracle_replaying().or.oracle_enabled(active_key)
  do ancestor=1,scope_depth
   retain_counters=retain_counters.or.oracle_enabled(parents(ancestor)%key)
  enddo
  if(len_trim(active_key)>0) then
   if(scope_depth==size(parents)) error stop 'oracle scope stack exhausted'
   scope_depth=scope_depth+1
   parents(scope_depth)%key=active_key
   parents(scope_depth)%event=active_event
   parents(scope_depth)%prefix=input_prefix
   ! Inactive scopes have no counters or hidden words to preserve. Avoid
   ! allocating two megabytes on the native heap for every disabled call.
   ! An enabled ancestor still needs every descendant's local bookkeeping.
   if(retain_counters) then
    parents(scope_depth)%local_keys=local_keys
    parents(scope_depth)%local_counts=local_counts
    parents(scope_depth)%seen=hidden_seen
   endif
   call move_alloc(pending,parents(scope_depth)%pending)
  endif
  active_key=key; active_event=event
  local_keys=''; local_counts=0; hidden_seen=''; input_prefix=''
  if(allocated(pending)) deallocate(pending)
 end subroutine
 subroutine oracle_replay_begin(prefix,key,event)
  character(len=*), intent(in) :: prefix,key
  integer, intent(in) :: event
  call oracle_scope_begin(key,event)
  input_prefix=prefix
 end subroutine
 subroutine oracle_local_begin(name,invocation)
  character(len=*), intent(in) :: name
  integer, intent(out) :: invocation
  integer :: slot,ancestor
  logical :: enabled_scope
  invocation=0
  if(len_trim(active_key)==0) return
  enabled_scope=oracle_enabled(active_key)
  do ancestor=1,scope_depth
   enabled_scope=enabled_scope.or.oracle_enabled(parents(ancestor)%key)
  enddo
  if(.not.enabled_scope) return
  do slot=1,size(local_keys)
   if(local_keys(slot)==name.or.local_keys(slot)=='') exit
  enddo
  if(slot>size(local_keys)) error stop 'oracle local keys exhausted'
  local_keys(slot)=name; local_counts(slot)=local_counts(slot)+1
  invocation=local_counts(slot)
 end subroutine
 subroutine buffer_record(records,name,code,width,rank_n,dims,lower,payload)
  type(pending_record), allocatable, intent(inout) :: records(:)
  character(len=*), intent(in) :: name
  integer, intent(in) :: code,width,rank_n,dims(5),lower(5)
  integer(int8), intent(in) :: payload(:)
  integer :: slot
  if(.not.allocated(records)) allocate(records(4096))
  do slot=1,size(records)
   if(records(slot)%name==name.or.records(slot)%name=='') exit
  enddo
  if(slot>size(records)) error stop 'oracle hidden records exhausted'
  records(slot)%name=name; records(slot)%code=code; records(slot)%width=width
  records(slot)%rank_n=rank_n; records(slot)%dims=dims; records(slot)%lower=lower
  records(slot)%payload=payload
 end subroutine
 subroutine remove_buffered(records,name)
  type(pending_record), allocatable, intent(inout) :: records(:)
  character(len=*), intent(in) :: name
  integer :: i,j
  if(.not.allocated(records)) return
  do i=1,size(records)
   if(records(i)%name=='') return
   if(records(i)%name/=name) cycle
   do j=i,size(records)-1
    records(j)=records(j+1)
    if(records(j)%name=='') exit
   enddo
   records(size(records))=pending_record()
   return
  enddo
 end subroutine
 subroutine oracle_scope_end()
  integer :: slot,unit
  if(allocated(pending)) then
   do slot=1,size(pending)
    if(pending(slot)%name=='') exit
    call open_record(active_key,'post',pending(slot)%name,active_event,pending(slot)%code, &
         pending(slot)%width,pending(slot)%rank_n,pending(slot)%dims,pending(slot)%lower,0,0,unit)
    write(unit) pending(slot)%payload
    close(unit)
   enddo
   deallocate(pending)
  endif
  active_key=''; active_event=0; input_prefix=''
  if(scope_depth>0) then
   active_key=parents(scope_depth)%key
   active_event=parents(scope_depth)%event
   input_prefix=parents(scope_depth)%prefix
   if(allocated(parents(scope_depth)%local_keys)) then
    local_keys=parents(scope_depth)%local_keys
    local_counts=parents(scope_depth)%local_counts
    hidden_seen=parents(scope_depth)%seen
    deallocate(parents(scope_depth)%local_keys,parents(scope_depth)%local_counts,parents(scope_depth)%seen)
   else
    local_keys=''; local_counts=0; hidden_seen=''
   endif
   call move_alloc(parents(scope_depth)%pending,pending)
   scope_depth=scope_depth-1
  endif
 end subroutine
 logical function oracle_replaying() result(replaying)
  integer :: ancestor
  replaying=len_trim(input_prefix)>0
  do ancestor=1,scope_depth
   replaying=replaying.or.len_trim(parents(ancestor)%prefix)>0
  enddo
 end function
 logical function first_hidden(name,seen) result(first)
  character(len=*), intent(in) :: name
  character(len=256), intent(inout) :: seen(:)
  integer :: slot
  first=.false.
  do slot=1,size(seen)
   if(seen(slot)==name) return
   if(seen(slot)=='') then
    seen(slot)=name;first=.true.;return
   endif
  enddo
  error stop 'oracle hidden keys exhausted'
 end function
 logical function oracle_scope_active() result(active)
  integer :: ancestor
  active=oracle_replaying().or.oracle_enabled(active_key)
  do ancestor=1,scope_depth
   active=active.or.oracle_enabled(parents(ancestor)%key)
  enddo
 end function
 integer function oracle_current_step() result(step)
  step=current_step
 end function
 subroutine oracle_set_context(ids, step, rank_id)
  integer(int32), intent(in) :: ids(:)
  integer, intent(in) :: step, rank_id
  owned_global_ids=ids
  global_ids=>owned_global_ids
  current_step=step
  current_rank=rank_id
 end subroutine
 subroutine oracle_set_native_context(ids, step, rank_id)
  ! Native mpas_pool_get_array returns persistent pointer storage. Borrow it
  ! during the driver scope instead of inserting an allocation into MPAS's
  ! heap. Standalone callers keep oracle_set_context's owned-copy contract.
  integer(int32), pointer, intent(in) :: ids(:)
  integer, intent(in) :: step,rank_id
  global_ids(1:)=>ids
  current_step=step
  current_rank=rank_id
 end subroutine
 subroutine oracle_restore_context(path,event)
  character(len=*), intent(in) :: path
  integer, intent(out) :: event
  integer :: unit,status,ca,nc,lo
  integer(int32) :: h(21)
  integer(int8) :: rawh(84)
  integer(int8), allocatable :: rawids(:)
  integer(int32), allocatable :: ids(:)
  character(len=8) :: magic
  character(len=256) :: k,p,n
  open(newunit=unit,file=path,access='stream',form='unformatted',status='old', &
       action='read',iostat=status)
  if(status/=0) error stop 'oracle context record missing'
  read(unit,iostat=status) magic,rawh
  h=transfer(rawh,h)
  if(status/=0 .or. magic/='ORCL0001') error stop 'oracle invalid context'
  nc=h(17); ca=h(18)
  if(nc<0 .or. ca<0 .or. ca>5) error stop 'oracle invalid context dimensions'
  allocate(ids(nc),rawids(nc*4)); read(unit) k,p,n,rawids
  ids=transfer(rawids,ids)
  close(unit)
  nullify(global_ids)
  if(allocated(owned_global_ids)) deallocate(owned_global_ids)
  if(ca>0) then
   lo=h(8+ca)
   allocate(owned_global_ids(max(0,lo+nc-1)))
   global_ids=>owned_global_ids; global_ids=0
   if(lo>0 .and. nc>0) global_ids(lo:lo+nc-1)=ids
  endif
  current_step=h(14); event=h(15); current_rank=h(16)
 end subroutine
 subroutine oracle_set_output(path)
  character(len=*), intent(in) :: path
  output_override=path
 end subroutine
 subroutine oracle_clear_output()
  output_override=''
 end subroutine
 logical function selected(text, value) result(yes)
  character(len=*), intent(in) :: text, value
  integer :: i, j
  yes=len_trim(text)==0 .or. trim(text)=='*'
  i=1
  do while(i<=len_trim(text))
   j=index(text(i:), ',')
   if(j==0) j=len_trim(text)-i+2
   if(trim(adjustl(text(i:i+j-2)))==trim(value)) yes=.true.
   i=i+j
  end do
 end function
 logical function oracle_enabled(key) result(yes)
  character(len=*), intent(in) :: key
  character(len=4096) :: directory, selection
  character(len=32) :: step_text
  integer :: status,ancestor
  yes=.false.
  if(len_trim(output_override)>0) then
   yes=.not.oracle_replaying().or.(len_trim(input_prefix)>0.and.key==active_key)
   do ancestor=1,scope_depth
    yes=yes.or.(len_trim(parents(ancestor)%prefix)>0.and.key==parents(ancestor)%key)
   enddo
   return
  endif
  call get_environment_variable('MPAS_ORACLE_DIR', directory, status=status)
  if(status/=0 .or. len_trim(directory)==0) return
  call get_environment_variable('MPAS_ORACLE_KEYS', selection, status=status)
  if(status/=0) selection=''
  if(.not.selected(trim(selection),key)) return
  call get_environment_variable('MPAS_ORACLE_STEPS', selection, status=status)
  if(status/=0) selection=''
  write(step_text,'(I0)') current_step
  yes=selected(trim(selection),trim(step_text))
 end function
 subroutine oracle_begin(key, event)
  character(len=*), intent(in) :: key
  integer, intent(out) :: event
  integer :: slot
  if(len_trim(key)>256) error stop 'oracle key exceeds 256 bytes'
  do slot=1,size(keys)
   if(keys(slot)==key .or. keys(slot)=='') exit
  enddo
  if(slot>size(keys)) error stop 'oracle keys exhausted'
  keys(slot)=key
  counts(slot)=counts(slot)+1
  event=counts(slot)
 end subroutine
 subroutine open_record(key, phase, name, event, code, width, rank_n, dims, lower, ca, la, unit)
  character(len=*), intent(in) :: key, phase, name
  integer, intent(in) :: event, code, width, rank_n, dims(5), lower(5), ca, la
  integer, intent(out) :: unit
  character(len=4096) :: directory, filename
  character(len=256) :: k, p, n
  character(len=96) :: suffix
  integer :: status, nc, i, ii
  integer(int32) :: header(21)
  integer(int32), allocatable :: ids(:)
  if(ca<0 .or. ca>rank_n .or. la<0 .or. la>rank_n) error stop 'oracle invalid axes'
  if(la>0 .and. la==ca) error stop 'oracle axes collide'
  nc=0
  if(ca>0) nc=dims(ca)
  allocate(ids(nc)); ids=0
  if(associated(global_ids)) then
   do i=1,nc
    ii=i+lower(ca)-1
    if(ii>=1 .and. ii<=size(global_ids)) ids(i)=global_ids(ii)
   enddo
  endif
  write(suffix,'(A,I10.10,A,I10.10,A,I6.6)') '.s',current_step,'.e',event,'.r',current_rank
  if(len_trim(output_override)>0) then
   filename=trim(output_override)//'.'//trim(phase)//'.'//trim(name)//'.bin'
  else
   call get_environment_variable('MPAS_ORACLE_DIR',directory,status=status)
   if(status/=0) error stop 'oracle missing output directory'
   filename=trim(directory)//'/'//trim(key)//trim(suffix)//'.'//trim(phase)//'.'//trim(name)//'.bin'
  endif
  k=key; p=phase; n=name
  header=[int(code,int32),int(width,int32),int(rank_n,int32),int(dims,int32),int(lower,int32), &
          int(current_step,int32),int(event,int32),int(current_rank,int32),int(nc,int32), &
          int(ca,int32),int(la,int32),256_int32,0_int32]
  open(newunit=unit,file=trim(filename),access='stream',form='unformatted',status='new', &
       iostat=status)
  if(status/=0) error stop 'oracle cannot create record (directory must exist; no overwrite)'
  if(iachar(transfer(1_int32,'a'))/=1) error stop 'oracle requires pinned little endian host'
  write(unit) 'ORCL0001', transfer(header,[0_int8],84), k, p, n, transfer(ids,[0_int8],nc*4)
 end subroutine
 subroutine oracle_header(path, code, width, rank_n, dims, lower, unit)
  character(len=*), intent(in) :: path
  integer, intent(out) :: code, width, rank_n, dims(5), lower(5), unit
  character(len=8) :: magic
  character(len=256) :: k,p,n
  integer(int32) :: h(21)
  integer(int8) :: rawh(84)
  integer(int8), allocatable :: rawids(:)
  integer(int32), allocatable :: ids(:)
  integer :: status
  open(newunit=unit,file=path,access='stream',form='unformatted',status='old',action='read', &
       iostat=status)
  if(status/=0) error stop 'oracle missing input record'
  read(unit,iostat=status) magic,rawh
  h=transfer(rawh,h)
  if(status/=0 .or. magic/='ORCL0001') error stop 'oracle invalid header'
  if(h(3)<0 .or. h(3)>5 .or. any(h(4:8)<0) .or. h(17)<0 .or. h(20)/=256) &
      error stop 'oracle malformed dimensions'
  code=h(1); width=h(2); rank_n=h(3); dims=h(4:8); lower=h(9:13)
  allocate(ids(h(17)),rawids(h(17)*4))
  read(unit,iostat=status) k,p,n,rawids
  ids=transfer(rawids,ids)
  if(status/=0) error stop 'oracle truncated metadata'
 end subroutine

#ifdef MPAS_USE_MPI_F08
 subroutine write_mpi_comm(key,phase,name,value,event,lower,cell_axis,level_axis)
  character(len=*), intent(in) :: key,phase,name
  type(MPI_Comm), intent(in) :: value
  integer, intent(in) :: event
  integer, optional, intent(in) :: lower(:),cell_axis,level_axis
