  endif
 end subroutine
 subroutine hidden_i4_1(name,value,invocation,phase,lower)
  character(len=*), intent(in) :: name,phase
  integer(int32), dimension(:), intent(inout) :: value
  integer, intent(in) :: invocation
  integer, optional, intent(in) :: lower(:)
  integer :: dims(5),lb(5),ancestor
  if(invocation==0) return
  if(phase=='pre') then
   if(oracle_enabled(active_key)) then
   if(first_hidden(name,hidden_seen)) then
    if(len_trim(input_prefix)>0) then
     call oracle_read(trim(input_prefix)//'.pre.'//trim(name)//'.bin',value)
    else
     call oracle_write(active_key,'pre',name,value,active_event,lower=lower)
    endif
   endif
   endif
   do ancestor=1,scope_depth
    if(.not.oracle_enabled(parents(ancestor)%key)) cycle
    if(first_hidden(name,parents(ancestor)%seen)) then
     if(len_trim(parents(ancestor)%prefix)>0) then
      call oracle_read(trim(parents(ancestor)%prefix)//'.pre.'//trim(name)//'.bin',value)
     else
      call oracle_write(parents(ancestor)%key,'pre',name,value,parents(ancestor)%event,lower=lower)
     endif
    endif
   enddo
  else if(phase=='post') then
   dims=1;lb=1
   dims(1:1)=shape(value)
   if(present(lower)) lb(1:1)=lower
   if(oracle_enabled(active_key)) call buffer_record(pending,name,3,4,1,dims,lb,transfer(value,[0_int8],4*product(dims)))
   do ancestor=1,scope_depth
    if(.not.oracle_enabled(parents(ancestor)%key)) cycle
    call buffer_record(parents(ancestor)%pending,name,3,4,1,dims,lb, &
         transfer(value,[0_int8],4*product(dims)))
   enddo
  else
   error stop 'oracle invalid hidden phase'
  endif
 end subroutine
 subroutine write_i4_1(key, phase, name, value, event, lower, cell_axis, level_axis)
  character(len=*), intent(in) :: key, phase, name
  integer(int32), dimension(:), intent(in) :: value
  integer, intent(in) :: event
  integer, optional, intent(in) :: lower(:), cell_axis, level_axis
  integer :: dims(5), lb(5), ca, la, unit
  if(.not.oracle_enabled(key)) return
  dims=1; lb=1; ca=0; la=0
  dims(1:1)=shape(value)
  if(present(lower)) then
   if(size(lower)/=1) error stop 'oracle lower bound rank mismatch'
   lb(1:1)=lower
  endif
  if(present(cell_axis)) ca=cell_axis
  if(present(level_axis)) la=level_axis
  call open_record(key,phase,name,event,3,4,1,dims,lb,ca,la,unit)
  write(unit) transfer(value,[0_int8],4*product(dims))
  close(unit)
 end subroutine
 subroutine read_i4_1(path, value)
  character(len=*), intent(in) :: path
  integer(int32), dimension(:), intent(out) :: value
  integer :: code,width,rank_n,dims(5),lb(5),unit,status
  integer(int64) :: bytes, position
  integer(int8), allocatable :: payload(:)
  call oracle_header(path,code,width,rank_n,dims,lb,unit)
  if(code/=3 .or. width/=4 .or. rank_n/=1) error stop 'oracle type/rank mismatch'
  if(any(dims(1:1)/=shape(value))) error stop 'oracle shape mismatch'
  allocate(payload(width*product(dims)))
  read(unit,iostat=status) payload
  if(status/=0) error stop 'oracle truncated payload'
  inquire(unit,size=bytes,pos=position)
  if(position/=bytes+1) error stop 'oracle trailing payload'
  value=reshape(transfer(payload,[0_int32]),shape(value))
  close(unit)
 end subroutine
 subroutine allocation_i4_2(name,value,lower)
  character(len=*), intent(in) :: name
  integer(int32), dimension(:,:), intent(inout) :: value
  integer, optional, intent(in) :: lower(:)
  integer :: invocation,ancestor,slot
  character(len=10) :: ordinal
  character(len=256) :: record,counter
  if(len_trim(name)+34>len(record)) error stop 'oracle allocation record name too long'
  counter='allocation.'//trim(name)
  call oracle_local_begin(counter,invocation)
  if(invocation==0) return
  write(ordinal,'(I10.10)') invocation
  record=trim(counter)//'.n'//ordinal
  if(oracle_enabled(active_key)) then
   if(len_trim(input_prefix)>0) then
    call oracle_read(trim(input_prefix)//'.pre.'//trim(record)//'.bin',value)
   else
    call oracle_write(active_key,'pre',record,value,active_event,lower=lower)
   endif
  endif
  do ancestor=1,scope_depth
   if(.not.oracle_enabled(parents(ancestor)%key)) cycle
   do slot=1,size(parents(ancestor)%local_keys)
    if(parents(ancestor)%local_keys(slot)==counter.or.parents(ancestor)%local_keys(slot)=='') exit
   enddo
   if(slot>size(parents(ancestor)%local_keys)) error stop 'oracle ancestor allocation keys exhausted'
   parents(ancestor)%local_keys(slot)=counter
   parents(ancestor)%local_counts(slot)=parents(ancestor)%local_counts(slot)+1
   write(ordinal,'(I10.10)') parents(ancestor)%local_counts(slot)
   record=trim(counter)//'.n'//ordinal
   if(len_trim(parents(ancestor)%prefix)>0) then
    call oracle_read(trim(parents(ancestor)%prefix)//'.pre.'//trim(record)//'.bin',value)
   else
    call oracle_write(parents(ancestor)%key,'pre',record,value,parents(ancestor)%event,lower=lower)
   endif
  enddo
 end subroutine
 subroutine hidden_alloc_i4_2(name,value,invocation,phase)
  character(len=*),intent(in) :: name,phase
  integer(int32), dimension(:,:),allocatable,intent(inout) :: value
  integer,intent(in) :: invocation
  integer :: code,width,rank_n,dims(5),lb(5),unit,ancestor
  logical :: state_present,first,dummy
  character(len=4096) :: allocation_prefix
  if(invocation==0) return
  state_present=allocated(value)
  first=.false.
  allocation_prefix=input_prefix
  if(phase=='pre') then
   if(len_trim(input_prefix)>0) first=first_hidden(trim(name)//'.allocation',hidden_seen)
   do ancestor=1,scope_depth
    if(len_trim(parents(ancestor)%prefix)==0) cycle
    if(first_hidden(trim(name)//'.allocation',parents(ancestor)%seen)) then
     first=.true.; allocation_prefix=parents(ancestor)%prefix
    endif
   enddo
  endif
  call oracle_hidden(trim(name)//'.present',state_present,invocation,phase)
  if(first) then
   if(allocated(value)) deallocate(value)
   if(state_present) then
    call oracle_header(trim(allocation_prefix)//'.pre.'//trim(name)//'.bin',code,width,rank_n,dims,lb,unit)
    close(unit)
    if(code/=3.or.width/=4.or.rank_n/=2) error stop 'oracle hidden allocation type/rank mismatch'
    allocate(value(lb(1):lb(1)+dims(1)-1,lb(2):lb(2)+dims(2)-1))
   endif
  endif
  if(state_present) then
   call oracle_hidden(name,value,invocation,phase,lower=lbound(value))
  else if(phase=='pre') then
   if(oracle_enabled(active_key)) dummy=first_hidden(name,hidden_seen)
   do ancestor=1,scope_depth
    if(oracle_enabled(parents(ancestor)%key)) dummy=first_hidden(name,parents(ancestor)%seen)
   enddo
  else if(phase=='post') then
   call remove_buffered(pending,name)
   do ancestor=1,scope_depth
    call remove_buffered(parents(ancestor)%pending,name)
   enddo
  endif
 end subroutine
