  if(present(cell_axis)) ca=cell_axis
  if(present(level_axis)) la=level_axis
  call open_record(key,phase,name,event,6,8,2,dims,lb,ca,la,unit)
  write(unit) transfer(value,[0_int8],8*product(dims))
  close(unit)
